// Node: "Compute Ear Triage Entry Node" (Script). Reads the native form
// fields collected on the preceding "Ear Symptoms & Details" intake node
// and computes which EXISTING node to enter the (unchanged) outcome/alert
// sub-graph at. Ported 1:1 from the original 14-node Ear question chain
// (2,6,13,15,17,68,82,87,97,99,102,122,123,134,146) — every branch below was
// validated against that graph's actual button links before being written
// here (see Zingtree Builder/Workflow JSONs/Spokane ENT/ear_logic_validation.py).
//
// Native `select` fields submit their OPTION TEXT as the value (Zingtree
// house rule), so every comparison below matches the exact text shown in
// this node's formfields — not an internal code.
//
// One finding carried forward from validation: node 6 ("Otorrhea, Hearing
// Loss?", reached only from the Pain branch once age >= 18) is vestigial —
// BOTH of its answers lead to 56 — so "Pain" routes straight there below
// with no follow-up questions at all, regardless of age.
//
// ETL pass (Sep 2026): nodes 135 ("Adult CI Protocol") and 147 ("Pediatric
// CI Protocol") carried byte-identical instructions — the age question that
// used to pick between them drove no actual difference in what staff saw,
// so it was dropped from the intake (no `ear_candidate_age` field anymore)
// and both cases now route to the single surviving node 135 (renamed
// "Cochlear Implant Coordinator Referral" since it now serves both ages).
// Node 147 was deleted.
//
// Downstream nodes 55/56/62/106/135/136/150/152/185/186/187/194 are
// UNTOUCHED — including node 56's own native "prior related surgery?"
// escalation button to 55, which still works exactly as before once the
// flow lands there.
(function () {
  var sym = ZT.getVariableValue("ear_symptom", "");
  var entry = "56"; // Straightforward Ear Group — the common default

  if (sym === "Hearing Loss" || sym === "Pressure / Fullness") {
    if (ZT.getVariableValue("ear_duration", "") === "<2 Weeks") {
      entry = (ZT.getVariableValue("ear_assoc", "") === "Dry & Painless Ear") ? "106" : "56";
    } else if (ZT.getVariableValue("ear_side", "") === "One Ear") {
      entry = "56";
    } else {
      var age = parseInt(ZT.getVariableValue("ear_age", "0"), 10);
      entry = (age >= 65) ? "152" : (age >= 18 ? "186" : "56");
    }
  } else if (sym === "Pain") {
    entry = "56"; // node 6 is vestigial — both original answers led here
  } else if (sym === "Itch") {
    entry = (ZT.getVariableValue("ear_status", "") === "Dry Ear & Hearing Normally") ? "62" : "56";
  } else if (sym === "Discharge") {
    if (ZT.getVariableValue("ear_duration2", "") === "<1 month") { entry = "56"; }
    else { entry = (ZT.getVariableValue("ear_has_tube", "") === "Yes, Ear Tube") ? "56" : "55"; }
  } else if (sym === "Tinnitus") {
    var tt = ZT.getVariableValue("ear_tinnitus_type", "");
    entry = (tt === "Pulse With Heartbeat") ? "55" : (tt === "Occur in Only One Ear" ? "186" : "187");
  } else if (sym === "Dizziness / Imbalance") {
    entry = "150";
  } else if (sym === "Speech Delay") {
    entry = "56";
  } else if (sym === "Referral for Hearing Test") {
    var concern = ZT.getVariableValue("ear_concern", "");
    if (concern === "Failed Hearing Screen") {
      entry = (ZT.getVariableValue("ear_hs_type", "") === "Newborn") ? "185" : "56";
    } else if (concern === "APD (Auditory Processing Disorder)") { entry = "194"; }
    else { entry = "56"; } // Speech Disorder
  } else if (sym === "Referral for Ear Tubes") {
    entry = "56";
  } else if (sym === "Referral for Auditory Implant Evaluation") {
    entry = (ZT.getVariableValue("ear_implant_type", "") === "Cochlear") ? "135" : "136";
  } else if (sym === "Wax") {
    entry = "126";
  }

  ZT.setFormData("ear_entry_node", entry);
})();

