// Node: "Compute Nose Triage Entry Node" (Script). Reads the native form
// fields collected on the preceding "Nose Symptoms & Details" intake node
// and computes which EXISTING node to enter the (unchanged) outcome/alert
// sub-graph at. Ported 1:1 from the original 8-node Nose question chain
// (39,32,103,101,100,27,96), plus node 177 which is fully replaced by the
// nose_bleeding field — every branch below was validated against that
// graph's actual button links before being written here (see Zingtree
// Builder/Workflow JSONs/Spokane ENT/nose_logic_validation.py).
//
// Native `select` fields submit their OPTION TEXT as the value (Zingtree
// house rule), so every comparison below matches the exact text shown in
// this node's formfields.
//
// Two findings carried forward from validation:
//  - Node 39 ("Nasal Trauma?") is vestigial: BOTH of its answers route to
//    61, so "Obstructed Nasal Breathing" goes straight to 61 below.
//  - Node 27's "Associated Sinonasal Symptoms?" sub-tree (27 -> 103 -> 61,
//    and 27 -> 96 -> 61) is likewise fully vestigial — every path out of
//    it lands on 61 regardless of the answers given — so "Facial
//    Pressure/Pain" goes straight to 61 below too.
//
// ETL pass (Sep 2026): the epistaxis "not actively bleeding" sub-chain used
// to ask "Is the nose packed?" (node 179) and "Blood-thinning medications?"
// (node 180) as two MORE single-purpose Content screens, then land on one
// of two near-identical scheduling-note nodes (181: "5 and 10 days", 182:
// "3 and 7 days") that differed only in the day range. Both questions are
// now native conditional fields on THIS intake screen (nose_packed,
// nose_blood_thinners), and this script stages the day-range paragraph as
// a transform so nodes 181/182 collapse into node 188 alone, rendering
// `${transforms.nose_day_range_html}`. Nodes 179, 180, 181, 182 were
// deleted; node 188's own "Continue" button now points straight to 61.
//
// Downstream nodes 60/61/62/66/178/188 are otherwise UNTOUCHED — including
// node 61's own native "prior related surgery?" escalation button to 60.
(function () {
  var sym = ZT.getVariableValue("nose_symptom", "");
  var entry = "61"; // Straightforward Nose Group — the common default

  if (sym === "Obstructed Nasal Breathing") {
    entry = "61"; // node 39 is vestigial — both original answers led here
  } else if (sym === "Nostril Drainage") {
    var sub = ZT.getVariableValue("nose_drainage_sub", "");
    if (sub === "Itchy/Watery Eyes with Sneezing") {
      entry = "66";
    } else if (sub === "Facial Pressure/Pain, Obstructed Nasal Breathing, or Smell Disturbance") {
      entry = "61"; // node 103 is vestigial — both durations led here
    } else {
      // No Other Symptoms
      if (ZT.getVariableValue("nose_nostril_scope", "") === "Only One Nostril") {
        entry = "60";
      } else {
        var age = parseInt(ZT.getVariableValue("nose_age", "0"), 10);
        entry = (age >= 65) ? "62" : "61";
      }
    }
  } else if (sym === "Postnasal Drainage") {
    entry = "62";
  } else if (sym === "Smell Disturbance") {
    entry = "61";
  } else if (sym === "Facial Pressure/Pain") {
    entry = "61"; // node 27's entire sub-tree is vestigial — every path led here
  } else if (sym === "Pain/Sore") {
    entry = "61";
  } else if (sym === "Epistaxis") {
    entry = (ZT.getVariableValue("nose_bleeding", "") === "Yes, Actively Bleeding") ? "178" : "188";
  }

  ZT.setFormData("nose_entry_node", entry);

  // Stage node 188's packed/day-range paragraph (empty when not packed —
  // node 188 always shows the "limit of 1 patient" note either way).
  var packed = ZT.getVariableValue("nose_packed", "");
  var dayRangeHtml = "";
  if (packed === "Yes, Packed") {
    var thinners = ZT.getVariableValue("nose_blood_thinners", "");
    var days = (thinners === "Yes, Blood Thinners") ? "5 and 10" : "3 and 7";
    dayRangeHtml =
      "<p><strong>The patient should be scheduled with a provider listed on the next page between " +
      days +
      " days from the time the nose was packed.</strong></p>" +
      "<p><strong>If there are no openings in that timeframe, please contact the triage nurse " +
      "(who might work with the on-call doctor) to manage the situation.</strong></p>";
  }
  ZT.setTransformData("nose_day_range_html", dayRangeHtml);
})();

