// Node: "Classify Other Symptom" (Script). The whole Other branch's logic and
// display content live here: it reads the native fields collected on the
// preceding "Other Symptoms & Details" intake screen, decides where the
// caller goes, and stages the alert/notice card the next screen renders.
//
// Replaces 30 nodes: 15 pure-question screens (5's own 23-button fan-out plus
// 24, 78, 81, 108, 112, 113, 114, 115, 116, 118, 127, 128, 201, 202), the 8
// single-button alert interstitials (107, 117, 120, 130, 137, 148, 199, 200)
// and the 7 terminal "Spokane ENT does not manage X" notices (90, 91, 92, 93,
// 151, 169, 183). The alert and notice cards below are the verbatim HTML those
// nodes carried -- one catalog entry each, rendered by one shared screen.
//
// Native `select` fields submit their OPTION TEXT as the value, so every
// comparison matches the exact text shown on the intake screen.
//
// Two vestigial questions were dropped on the way: node 113 ("Face
// Lump/Lesion": On the Skin / Under the Skin) and node 114 ("Mouth
// Lump/Lesion": Lip, Tongue, Jaw, or Cheek / Tonsil or Palate). Both answers
// of each led to node 59, so neither question ever changed an outcome.
//
// Shared destinations (56, 58, 59, 61, 62, 63, 64, 66, 75, 76, 77, 80, 129,
// 150, 167, 184) are UNTOUCHED -- they serve other branches too.
(function () {
  // --- display catalogs: verbatim card HTML from the nodes this replaces ---
  var ALERT_CARDS = {
    "107": "<div class=\"cse-card cse-card--danger\"><div class=\"cse-card-head\"><span class=\"cse-card-icon\">&#9888;</span><span class=\"cse-card-title\">Urgent</span></div><div class=\"cse-card-body\"><p><strong>Acute facial paralysis suggests bell&#39;s palsy, a condition that requires treatment urgently. The appointment and audiogram should be scheduled within 3 business days.</strong></p><p><strong>If none of the identified providers are available within that timeframe, please triage this through the triage nurse.</strong></p><p><strong>Click the following button to continue.</strong></p></div></div>",
    "117": "<div class=\"cse-card cse-card--danger\"><div class=\"cse-card-head\"><span class=\"cse-card-icon\">&#9888;</span><span class=\"cse-card-title\">Urgent</span></div><div class=\"cse-card-body\"><p><strong>Bring this to the attention of the on-call sinus MA to triage the fracture.</strong></p><p>The appointment should be scheduled 3-7 days following injury. &nbsp;Try to schedule with provider who has surgery availability during this timeframe. &nbsp;Communicate with surgery schedulers for options. &nbsp;</p><p>If the referral arrives between 8 and 14 days following injury, the patient should be scheduled within 1 business day. &nbsp;</p><p>If the referral arrives&nbsp;15 days or more following injury, the patient should be scheduled either through the aesthetic or nose pathways, depending on the chief complaint.</p><p>In addition to those individuals in the straightforward trauma group, nasal injuries can also be scheduled with the following individuals: call, johnson, ledeboer, bisbee.</p><p><strong>Click the following button to continue.</strong></p></div></div>",
    "120": "<div class=\"cse-card cse-card--danger\"><div class=\"cse-card-head\"><span class=\"cse-card-icon\">&#9888;</span><span class=\"cse-card-title\">Urgent</span></div><div class=\"cse-card-body\"><p><strong>Ear trauma that results in swelling suggests an auricular hematoma. &nbsp;</strong></p><p><strong>The&nbsp;</strong><strong>30 minute appointment</strong><strong>&nbsp;should be scheduled&nbsp;</strong><strong>within 3 business days</strong><strong>. &nbsp;</strong></p><p><strong>If none of the identified providers are available within that timeframe, please triage this through the triage nurse.</strong></p><p><strong>Click the following button to continue.</strong></p></div></div>",
    "130": "<div class=\"cse-card cse-card--danger\"><div class=\"cse-card-head\"><span class=\"cse-card-icon\">&#9888;</span><span class=\"cse-card-title\">Urgent</span></div><div class=\"cse-card-body\"><p><strong>Unless determined that the patient needs immediate management in the ER, the appointment should be scheduled&nbsp;within 2 business days. &nbsp;</strong></p><p><strong>Children must be scheduled before noon and counseled regarding NPO after midnight. &nbsp;</strong></p><p><strong>If none of the identified providers are available within that timeframe, please contact the triage nurse.</strong></p><p><strong>Click the following button to continue.</strong></p></div></div>",
    "137": "<div class=\"cse-card cse-card--caution\"><div class=\"cse-card-head\"><span class=\"cse-card-icon\">&#128337;</span><span class=\"cse-card-title\">Audiogram Reminder</span></div><div class=\"cse-card-body\"><p><strong>Chronic or intermittent facial weakness without a neck lump should be evaluated with a pre-appointment audiogram as well.</strong></p><p><strong>Click the following button to continue.</strong></p></div></div>",
    "148": "<div class=\"cse-card cse-card--danger\"><div class=\"cse-card-head\"><span class=\"cse-card-icon\">&#9888;</span><span class=\"cse-card-title\">Urgent</span></div><div class=\"cse-card-body\"><p><strong>The appointment should be scheduled&nbsp;</strong><strong>within 3 business days</strong><strong>. &nbsp;Try to schedule with provider who has surgery availability during this timeframe. &nbsp;</strong></p><p><strong>Communicate with surgery schedulers for options. &nbsp;If none of the identified providers are available within that timeframe, please contact the triage nurse (ENT and general surgery can both be queried).</strong></p><p><strong>Click the following button to continue.</strong></p></div></div>",
    "199": "<div class=\"cse-card cse-card--caution\"><div class=\"cse-card-head\"><span class=\"cse-card-icon\">&#128337;</span><span class=\"cse-card-title\">Scheduling Note</span></div><div class=\"cse-card-body\"><p><strong>Ask the patient if there are any associated auditory symptoms (hearing loss, fullness, tinnitus). &nbsp;If yes, schedule an audiogram to occur before the visit. &nbsp;If no, schedule only the visit.</strong></p><p><strong>Click the following button to continue.</strong></p></div></div>",
    "200": "<div class=\"cse-card cse-card--caution\"><div class=\"cse-card-head\"><span class=\"cse-card-icon\">&#128337;</span><span class=\"cse-card-title\">Scheduling Note</span></div><div class=\"cse-card-body\"><p><br></p><p><strong>Patients triaging through the following pathways who are self-referred or dentist-referred must be scheduled with an APP listed in the provider group.</strong></p><p><strong>Patients triaging through the following pathways who are physician-referred, APP-referred, or oral surgeon-referred can be scheduled with any of the individuals listed in the provider group.</strong></p></div></div>",
  };

  var NOTICE_CARDS = {
    "90": "<div class=\"cse-card cse-card--neutral\"><div class=\"cse-card-head\"><span class=\"cse-card-icon\">&#8505;</span><span class=\"cse-card-title\">No Rash</span></div><div class=\"cse-card-body\"><p><strong>Spokane ENT does not manage rash. &nbsp;The patient should be instructed to seek care elsewhere.</strong></p></div></div>",
    "91": "<div class=\"cse-card cse-card--neutral\"><div class=\"cse-card-head\"><span class=\"cse-card-icon\">&#8505;</span><span class=\"cse-card-title\">Requires referral from a gastroenterologist</span></div><div class=\"cse-card-body\"><p><strong>Spokane ENT does not manage Eosinophilic Esophagitis. &nbsp;</strong><strong>If the gastroenterologist is referring for management of Eosinophilic Esophagitis, the patient should be instructed to seek care elsewhere.</strong></p></div></div>",
    "92": "<div class=\"cse-card cse-card--neutral\"><div class=\"cse-card-head\"><span class=\"cse-card-icon\">&#8505;</span><span class=\"cse-card-title\">TMJ</span></div><div class=\"cse-card-body\"><p><strong>Inform the patient that TMJ treatment is not available at Spokane ENT. &nbsp;</strong></p><p><strong>If the patient is evaluated by a dentist or oral surgeon and found to have a TMJ disorder impacted by an otolaryngologic disease, then the referral from that provider will be reviewed and scheduling considered.</strong></p></div></div>",
    "93": "<div class=\"cse-card cse-card--neutral\"><div class=\"cse-card-head\"><span class=\"cse-card-icon\">&#8505;</span><span class=\"cse-card-title\">Headache (Without Facial Pressure/Pain)</span></div><div class=\"cse-card-body\"><p><strong>This requires a referral from a PCP or neurologist.</strong></p></div></div>",
    "151": "<div class=\"cse-card cse-card--neutral\"><div class=\"cse-card-head\"><span class=\"cse-card-icon\">&#8505;</span><span class=\"cse-card-title\">Food/Medication Allergy</span></div><div class=\"cse-card-body\"><p><strong>Spokane ENT does not evaluate patients without otolaryngologic symptoms in order to facilitate food/medication allergy testing.</strong></p></div></div>",
    "169": "<div class=\"cse-card cse-card--neutral\"><div class=\"cse-card-head\"><span class=\"cse-card-icon\">&#8505;</span><span class=\"cse-card-title\">Trigeminal Neuralgia</span></div><div class=\"cse-card-body\"><p><strong>Spokane ENT does not manage Trigeminal Neuralgia. &nbsp;</strong></p><p><strong>The patient should be instructed to seek care elsewhere.</strong></p></div></div>",
    "183": "<div class=\"cse-card cse-card--neutral\"><div class=\"cse-card-head\"><span class=\"cse-card-icon\">&#8505;</span><span class=\"cse-card-title\">Aesthetic Services</span></div><div class=\"cse-card-body\"><p><strong>Spokane ENT does not offer these aesthetic services. &nbsp;The patient should be counseled to seek care elsewhere, such as Sand Plastic Surgery.</strong></p></div></div>",
  };

  var sym = ZT.getVariableValue("other_symptom", "");

  // Out-of-scope symptoms: one shared notice screen, catalog keyed by symptom.
  var NOTICE_BY_SYMPTOM = {
    "Rash": "90",
    "TMJ Pain": "92",
    "Trigeminal Neuralgia": "169",
    "Food / Medication Allergy": "151",
    "Heartburn / Acid Taste": "91",
    "Headache (Without Facial Pressure / Pain)": "93"
  };

  var entry = "77";     // Physician Triage -- the tree's own catch-all
  var final = "";       // only used when entry is "alert"
  var alertKey = "";
  var noticeKey = "";

  function goAlert(key, dest) { entry = "alert"; alertKey = key; final = dest; }
  function goNotice(key) { entry = "notice"; noticeKey = key; }

  if (NOTICE_BY_SYMPTOM[sym]) {
    goNotice(NOTICE_BY_SYMPTOM[sym]);
  } else if (sym === "Lump/Lesion") {
    var loc = ZT.getVariableValue("other_lump_location", "");
    if (loc === "Face") { entry = "59"; }
    else if (loc === "Nose/Sinus") { entry = "61"; }
    else if (loc === "Biopsy-Proven Cancer") { entry = "58"; }
    else if (loc === "Ear") { goAlert("199", "56"); }
    else if (loc === "Mouth") {
      if (ZT.getVariableValue("other_mouth_discovery", "") === "Discovered incidentally by your dentist") {
        goAlert("200", "64");
      } else {
        goAlert("200", ZT.getVariableValue("other_mouth_palpable", "") === "Can see or feel" ? "59" : "64");
      }
    } else if (loc === "Neck") {
      var t = ZT.getVariableValue("other_neck_lump_type", "");
      if (t === "Thyroid" || t === "Parathyroid") { entry = "167"; }
      else if (t === "Other") { entry = "58"; }
      else { entry = "59"; }
    }
  } else if (sym === "Trauma") {
    var tt = ZT.getVariableValue("other_trauma_type", "");
    if (tt === "Ear Swelling") { goAlert("120", "75"); }
    else if (tt === "Nasal Deformity") { goAlert("117", "75"); }
    else if (tt === "Facial Fracture") { entry = "76"; }
    else { entry = "77"; }
  } else if (sym === "Foreign Body") {
    var fb = ZT.getVariableValue("other_fb_location", "");
    if (fb === "Ear") { goAlert("130", "56"); }
    else if (fb === "Nose") { goAlert("130", "61"); }
    else if (ZT.getVariableValue("other_fb_throat_symptoms", "") === "Drooling, Cough, or Noisy Breathing") {
      goAlert("130", "129");
    } else { goAlert("130", "64"); }
  } else if (sym === "Cleft Lip/Palate") {
    entry = "184";
  } else if (sym === "Snoring/OSA") {
    var age = ZT.getVariableValue("other_osa_age", "");
    if (age === "<3") { entry = "63"; }
    else if (age === ">3 but <18") { entry = "64"; }
    else { entry = ZT.getVariableValue("other_sleep_study", "") === "Yes, Sleep Study" ? "80" : "62"; }
  } else if (sym === "Tongue/Lip Tie") {
    entry = "64";
  } else if (sym === "Establish for Tracheostomy Care") {
    entry = "63";
  } else if (sym === "Facial Weakness") {
    if (ZT.getVariableValue("other_facial_lump", "") === "New Neck / Face Lump") { entry = "58"; }
    else { goAlert(ZT.getVariableValue("other_facial_duration", "") === "<2 weeks" ? "107" : "137", "56"); }
  } else if (sym === "Superior Canal Dehiscence" || sym === "Ear Crystals (Canaliths)") {
    entry = "150";
  } else if (sym === "Itchy Eyes/Sneezing") {
    entry = "66";
  } else if (sym === "Preoperative Vocal Cord Check") {
    entry = "64";
  } else if (sym === "Referred for Temporal Artery Biopsy") {
    goAlert("148", "59");
  } else if (sym === "Mouth Pain") {
    entry = "59";
  } else if (sym === "Aesthetic") {
    var c = ZT.getVariableValue("other_aesthetic_concern", "");
    if (c === "Mohs Defect") { entry = "58"; }
    else if (c === "Other Congenital") { entry = "59"; }
    else { goNotice("183"); }
  }

  ZT.setFormData("other_entry_node", entry);
  ZT.setFormData("other_final_node", final);
  ZT.setTransformData("other_alert_html", alertKey ? ALERT_CARDS[alertKey] : "");
  ZT.setTransformData("other_notice_html", noticeKey ? NOTICE_CARDS[noticeKey] : "");
})();
